  [1231000] = { nil, "$N2秒ごとに$N1のFireダメージを受けています。", nil, 0x608ea152, "mu" },
  [1231010] = { "Vishasが敵のプレイヤーに印を付けます。印を付けられた対象が呪文を詠唱すると、Vishasがその方向へナイフを投げます。", "呪文を唱えると、Vishasがあなたに向かってナイフを投げてきます。", 0x7aee6290, 0x87862931, "uu" },
  [1231011] = { "Vishasが短剣の1本を敵に向かって投げ、最初に命中した敵に$N1のShadowダメージを与えます。ナイフがTortuous Rebukeを受けているプレイヤーに命中すると、出血も与えます。", nil, 0x81333075, nil, "um" },
  [1231012] = { nil, "Vishasに苦しめられています。$N2秒ごとに$N1のShadowダメージを受けます。", nil, 0x610f4cae, "mu" },
  [1231024] = { "Portiporterを自分で使ってみて、何が騒ぎになっているのか確かめます。\n\nNew Avalonでのみ、他の被験者で比較的安全だと確認してから使用できます。", nil, 0x5565caac, nil, "um" },
  [1231085] = { "魔法を込めた射撃を放ち、狭い範囲の敵を絡め取ります。", nil, 0xfb8e3bc8, nil, "um" },
  [1231087] = { nil, "スタンしています。", nil, 0x27f95286, "mu" },
  [1231091] = { "装置に好きな量の火薬を入れて、ボタンを押します。\n\n入れた火薬の量に応じて、速度と、重傷を負うか死亡する可能性が高まります。\n\nNew Avalonでのみ使用できます。", "移動速度が$N1%上昇しています", 0x0469fc89, 0xda8d4a05, "uu" },
  [1231095] = { "対象の精神を襲い、$N1のShadowダメージを与え、$D1の間、受けるShadowダメージを$N2増加させます。", "受けるShadowダメージが$N1増加しています。", 0xbee251eb, 0xc866cf0e, "uu" },
  [1231098] = { nil, "$N2秒ごとに$N1のダメージを受けます。", nil, 0x6e147642, "mu" },
  [1231102] = { "$D1持続する鋼の旋風で近くの敵を攻撃し、$D2ごとに武器ダメージに加えて$N2のダメージを与えます。術者は一時的に魔法への耐性を得ます。", "魔法に対する免疫があります。\n通常のダメージに加え、$D1ごとに近くの敵に$N1のダメージを与えています。", 0xd1fe8fef, 0x059c0337, "uu" },
  [1231123] = { "Pepeを呼び出して、冒険に連れて行きましょう！", "Pepeがあなたの冒険に加わりました！", 0x5d1b97e4, 0x08c375ce, "uu" },
  [1231124] = { "自分の体力を$N1回復し、$D1の間、筋力を$N2上昇させます。", "筋力が$N1増加しています。", 0x246dbbdf, 0x90d9af1c, "uu" },
  [1231128] = { "近接武器に永続的なエンチャントを施し、近接攻撃時にしばしば$N1回復し、$D1の間、筋力を$N2上昇させます。", nil, 0xb721ecf3, nil, "um" },
  [1231138] = { "マナを$N1回復し、$D1の間、Spell Powerを$N2上昇させます。", "呪文の威力が$N1増加します。", 0x4fb14ee8, 0x4e1d481d, "uu" },
