  [1231157] = { nil, "スタンしています。", nil, 0x27f95286, "mu" },
  [1231162] = { "マナを$N1回復し、$D1の間、Spell Powerを$N2上昇させます。", "呪文の威力が$N1増加します。", 0x4fb14ee8, 0x4e1d481d, "uu" },
  [1231164] = { "近接武器に永続的なエンチャントを施し、呪文を命中させたときにしばしばマナを$N1回復し、$D1の間、Spell Powerを$N2上昇させます。", nil, 0x02f53eee, nil, "um" },
