  [1231254] = { "$D1の間、Defenseを$N1、アーマーを$N2上昇させます。", "Defenseが$N1上昇しています。\nアーマーが$N2増加しています。", 0x2298094b, 0x95cb6445, "uu" },
  [1231258] = { "近接攻撃時に一定確率で敵に腐敗を与え、$D2の間、$N2秒ごとに術者の周囲半径$N3ヤード内のすべての敵に$N1のNatureダメージを与えます。これらの対象の攻撃速度も$N5%低下します。", nil, 0xeb0f65a2, nil, "um" },
