  [1231289] = { "Will of the Mountainを呼び起こし、$D1の間、与える物理ダメージを$N1%、アーマーを$N2、体の大きさを$N3%増加させます。", "与える物理ダメージが$N1%、アーマーが$N2、体の大きさが$N3%増加します。", 0xff890821, 0x271ce565, "uu" },
