  [1231310] = { "対象を侵入者として印を付け、$D1の間、Stealth、Invisibility、変装を使えなくします。", "侵入者だと見破られたため、隠密、透明化、変装が使えません。", 0xe6941441, 0xc6671ddf, "uu" },
  [1231312] = { nil, "スタンしています。", nil, 0x27f95286, "mu" },
