  [1231317] = { "対象の最大体力の$N1%を物理ダメージとして与え、さらに$D2の間、$D1ごとに$N2%を与えます。\n\n効果が切れたとき、対象の現在の体力に応じた確率で、傷がRabiesに変わります。", "$D1ごとに最大体力の$N1%をPhysicalダメージとして受けています。\n\nこの効果が切れたときの体力が低いほど、Rabiesに感染する可能性が高くなります。", 0x5742609d, 0xb1bea5d8, "uu" },
  [1231324] = { "移動速度が$N1%低下しています。$D2の間、$D1ごとに最大体力の$N2%を物理ダメージとして受けています。\n\n治療しなければ死にます。", "移動速度が$N1%低下しています。$D2の間、$D1ごとに最大体力の$N2%をPhysicalダメージとして受けます。\n\n手当てをしないと死亡します。", 0x415b1895, 0x3e9fb941, "uu" },
  [1231330] = { "最大$N2体の敵から生命力を$N1奪い、吸い取った敵ごとに筋力または敏捷性を$N3得ます。最大$N4回までスタックします。", nil, 0xb57c8e0d, nil, "um" },
