  [1231343] = { "Shades of Balnazzarが、他のプレイヤーから$N1ヤード以内にいないプレイヤーを打ち、$N2のShadowダメージを与えます。", "Shades of Balnazzarが、他のプレイヤーから$N1ヤード以内にいないプレイヤーを襲い、$N2のShadowダメージを与えます。", 0xf64841d3, 0xf64841d3, "uu" },
