  [1231560] = { "Duplicity and Deceptionの追加攻撃が、追加攻撃を$N1回発生させるようになります。", nil, 0x3c6b4b42, nil, "um" },
  [1231578] = { "体力を即座に$N1回復しますが、その量の$N2%を時間をかけて受けることになります。\n\nこの効果の症状は、$D1の毒か、$D2の病気として現れます。", nil, 0x998c6850, nil, "um" },
  [1231579] = { "変色した回復ポーションを飲んだため、継続的にダメージを受けます。", "$D1ごとに$N1のNatureダメージを受けています。", 0x6f74e28c, 0x0c4dce3b, "uu" },
  [1231580] = { "変色した回復ポーションを飲んだため、継続的にダメージを受けます。", "$D1ごとに$N1のShadowダメージを受けています。", 0x6f74e28c, 0xf8147610, "uu" },
  [1231582] = { nil, "スタンしています。", nil, 0x27f95286, "mu" },
  [1231585] = { nil, "周期的に攻撃速度とダメージが上昇します。精神集中中は、受けるダメージが$N1%減少します。", nil, 0x18b693d1, "mu" },
  [1231586] = { "Focus Fireを使うと、消費したスタックごとに、$D1の間、あなたとペットの与えるダメージが$N1%増加するようになります。", nil, 0x595fbf8a, nil, "um" },
  [1231587] = { nil, "攻撃速度が$N1%上昇します。ダメージが$N2%増加します。", nil, 0xb581b4fe, "mu" },
  [1231588] = { "Nordassilの枝から生まれた古代の炎を使って、刃を熱します。", nil, 0x2fc2f133, nil, "um" },
  [1231589] = { "熱した刃をWell of Eternityの水で焼き入れします。", nil, 0xc32856b5, nil, "um" },
  [1231590] = { "$D1の間、ペットの与えるダメージを$N1%増加させます。", "ペットの与えるダメージが$N1%増加します。", 0x4214ff51, 0xafe82fd9, "uu" },
  [1231591] = { "$D1の間、与えるダメージを$N1%増加させます。", "与えるダメージが$N1%増加します。", 0x560ef8d4, 0x6a8712db, "uu" },
  [1231592] = { "対象に海の呪いをかけます。呪いが解除されなければ、対象は溺れます。", "深い海があなたを待っています……", 0xf969748b, 0xb67613fc, "uu" },
  [1231594] = { "浅瀬の誘惑を感じながら溺れていきます。", nil, 0x88fac5ae, nil, "um" },
  [1231595] = { "遠隔攻撃時に$N1%の確率でStrand of Fateを生成し、移動しながら遠隔攻撃を使えるようになります。Strandsは最大$N2回まで重なり、$D1持続します。", nil, 0xaf28dc9f, nil, "um" },
  [1231601] = { nil, "移動しながら射撃や遠隔攻撃ができます。", nil, 0x244c9dbc, "mu" },
  [1231604] = { { "Strands of Fateを消費し、$D1の間スタックごとに筋力が$N1増加し、次にプレイヤー以外が操作する対象へ放つStrikeがSerpent Stingを付与します。消費したスタックごとに$N3秒持続し、更新はできません。", "Strands of Fateを即座に$N1生成します。", shape = { "3/1", "1/0" } }, "新たなStrands of Fateを生み出せません。", 0xcf40a045, 0xe7e6c6f3, "uu" },
  [1231605] = { "$D1の間、Scarlet Cannonに変身し、遠隔攻撃が爆発して、対象から$N3ヤード以内のすべての敵に$N2のFireダメージを与えるようにします。", "ドカーン！", 0x1a3745d1, 0x9133cb1a, "uu" },
  [1231612] = { "$D1以内に行う次の通常の近接攻撃が、呪文の威力の$N2倍のArcaneダメージを与え、対象を$D2の間眠らせます。", "次の通常の近接攻撃が呪文の威力の$N1倍のArcaneダメージを与え、$D1の間、目標を眠らせます。", 0x847ecfcc, 0x9afd5de5, "uu" },
  [1231614] = { "$D1以内に行う次の近接攻撃が、呪文の威力に応じたArcaneダメージを与え、$D2の間、対象を眠らせます。", "次の近接攻撃が呪文の威力に応じたArcaneダメージを与え、対象を$D1眠らせます。", 0xcd74a109, 0x9d59d9aa, "uu" },
  [1231615] = { "プレイヤーをGnomereganへ送ります。", nil, 0x187b8984, nil, "um" },
  [1231616] = { nil, "眠っています。", nil, 0x5339954e, "mu" },
  [1231618] = { "武器ダメージの$N1%を与えて対象に火をつけ、$D1かけてRadiantダメージを与えます。", "毎秒Radiantダメージを受けています。", 0xd82900a6, 0xf7483743, "uu" },
  [1231620] = { "周期的なダメージを与えると、$N1%の確率で$D1の間、呪文ダメージと回復量が$N2上昇します。", nil, 0x9cab1bdc, nil, "um" },
  [1231623] = { nil, "与える魔法ダメージと回復量が$N1増加します。", nil, 0x07aebb47, "mu" },
  [1231624] = { "周期的でないFireダメージを与えると、$N1%の確率で$D1の間、与えるFireダメージが$N2%増加します。", nil, 0x1a06ba7f, nil, "um" },
  [1231625] = { nil, "与えるFireダメージが$N1%増加します。", nil, 0x6d6712fb, "mu" },
  [1231628] = { "ダメージ呪文を命中させたとき一定の確率で、対象の上にMirageを作り出し、$D1の間、近くの敵に秘術ダメージを与えます。", nil, 0xdc4684a3, nil, "um" },
  [1231636] = { "Shades of Balnazzarが、他のプレイヤーから$N1ヤード以内にいないプレイヤーを打ち、$N2のShadowダメージを与えます。", nil, 0x952517cc, nil, "um" },
  [1231644] = { "Shades of Balnazzarが、他のプレイヤーから$N1ヤード以内にいないプレイヤーを打ち、$N2のShadowダメージを与えます。", nil, 0x952517cc, nil, "um" },
  [1231645] = { "Shades of Balnazzarが、他のプレイヤーから$N1ヤード以内にいないプレイヤーを打ち、$N2のShadowダメージを与えます。", nil, 0x952517cc, nil, "um" },
  [1231646] = { "Shades of Balnazzarが、他のプレイヤーから$N1ヤード以内にいないプレイヤーを打ち、$N2のShadowダメージを与えます。", nil, 0x952517cc, nil, "um" },
