  [1231656] = { "Mind Flay、Fire Blast、Drain Lifeの呪文の射程が$N1ヤード延長されますが、Mind Flayは敵を減速させなくなります。", nil, 0xe42705c1, nil, "um" },
  [1231657] = { "Mind Flay、Fire Blast、Drain Lifeの射程が$N1ヤード延びますが、Mind Flayで敵の移動速度が低下しなくなります。", nil, 0xd1764add, nil, "um" },
  [1231662] = { "Mind Flay、Fire Blast、Drain Lifeの射程が$N1ヤード延びますが、Mind Flayで敵の移動速度が低下しなくなります。", nil, 0xd1764add, nil, "um" },
  [1231663] = { "Mind Flay、Fire Blast、Drain Lifeの射程が$N1ヤード延びますが、Mind Flayで敵の移動速度が低下しなくなります。", nil, 0xd1764add, nil, "um" },
  [1231681] = { "体力が$N1%を超えている間、回復量が$N2増加しますが、回復呪文を唱えるたびに最大体力の$N3%を犠牲にします。この効果を受けている間は、直接対象にした周期的でない回復しか受けられません。（Toggled Effect）", "大義のために自らを犠牲にしています。\n直接目標にした、継続効果ではない治療しか受けられません。", 0x0d94924e, 0xfe1f822a, "uu" },
  [1231683] = { nil, "回復量が$N1増加します。\n回復するたびに、総体力の$N2%を犠牲にします。", nil, 0x099f8137, "mu" },
  [1231694] = { "敵にダメージを与える呪文を詠唱すると、その敵を$D1の間Condemn状態にします。その敵がダメージを与えるたびに、攻撃された対象は最大体力の$N2%回復します。効果は$D2、または最大$N4回の攻撃まで持続します。（クールダウン$N5秒）", nil, 0xcd95c960, nil, "um" },
  [1231695] = { nil, "この対象からの攻撃を受けると体力が$N1%回復します。", nil, 0x59c22f12, "mu" },
  [1231698] = { "$N1ヤード以内に敵がいない場合、$N4秒ごとに$N2ヤード以内のすべてのパーティーメンバーを$N3回復します。パーティーが一度にFealtyを誓えるプレイヤーは一人だけです。", nil, 0xce746732, nil, "um" },
  [1231700] = { nil, "$N2秒ごとに$N1を回復しています。", nil, 0x32d12c13, "mu" },
  [1231708] = { "$N1ヤード以内に敵がいない場合、近くのパーティメンバー全員の体力を$N3ごとに$N2回復します。一つのパーティがFealtyを誓えるのは、一度に一人のプレイヤーだけです。", nil, 0x47469900, nil, "um" },
  [1231752] = { "体が重くなりました！20分間、移動速度が25%低下しました。", "移動速度が25%低下します。", 0xc439e27f, 0x9c38ce50, "uu" },
