  [1231776] = { "BalnazzarがTyr's Handを闇に沈め、すべてのプレイヤーを沈黙させます。", "Tyr's Handを闇に沈め、すべてのプレイヤーを沈黙させます。", 0xd7dab647, 0xfa2ebbc5, "uu" },
  [1231777] = { "BalnazzarがTyr's Handを闇に沈め、すべてのプレイヤーを沈黙させます。", "沈黙させられています。", 0x9526257c, 0x20816e34, "uu" },
