  [1231838] = { "Balnazzarが死肉食いの虫の群れを解き放ってプレイヤーに取り付かせ、$D2の間、$D1ごとに$N3ヤード以内の味方に$N1のShadowダメージを与えさせます。この効果は重なります。", nil, 0x95266679, nil, "um" },
  [1231839] = { "Balnazzarが死肉食いの虫の群れを解き放ってプレイヤーに取り付かせ、$D2の間、$D1ごとに$N3ヤード以内の味方に$N1のShadowダメージを与えさせます。この効果は重なります。", nil, 0x95266679, nil, "um" },
  [1231840] = { "Balnazzarが死肉食いの虫の群れを解き放ってプレイヤーに取り付かせ、$D2の間、$D1ごとに$N3ヤード以内の味方に$N1のShadowダメージを与えさせます。この効果は重なります。", nil, 0x95266679, nil, "um" },
  [1231843] = { "Balnazzarがプレイヤーに支配の印を付けます。$N1後、効果を受けたプレイヤーと$N2ヤード以内の味方は$N3の間魅了されます。", nil, 0x6124f5fb, nil, "um" },
