  [1231896] = { "$D1の間、Mr. Bigglesworthの聡明さを授けます。", "筋力が$N1、敏捷性が$N2、攻撃力が$N3、遠隔攻撃力が$N4、すべての呪文と攻撃のクリティカル率が$N5%、近接攻撃と遠隔攻撃のヘイストが$N6%、アーマー貫通が$N7増加しています。", 0xbba3f8bb, 0xa1e3cbe9, "uu" },
  [1231897] = { "インファーナルが激しく邪悪に燃え、$D1ごとに$N2ヤード以内の敵に$N1のFireダメージを与えますが、その光はSuppressive Darknessを無効にもします。", nil, 0x9526698d, nil, "um" },
  [1231898] = { "インファーナルが激しく邪悪に燃え、$D1ごとに$N2ヤード以内の敵に$N1のFireダメージを与えますが、その光はSuppressive Darknessを無効にもします。", "$D1ごとに$N2ヤード以内の敵に$N1のFireダメージを与え、Suppressive Darknessに対する免疫も得ます。", 0xde19de78, 0x28def358, "uu" },
  [1231899] = { "BalnazzarがinfernalをScarlet Lightbearerの妨害に呼び出し、$N2ヤード以内に$N1のFireダメージを与え、命中したプレイヤーを$N3の間スタンさせます。", nil, 0x9526a7f9, nil, "um" },
  [1231900] = { "BalnazzarがinfernalをScarlet Lightbearerの妨害に呼び出し、$N2ヤード以内に$N1のFireダメージを与え、命中したプレイヤーを$N3の間スタンさせます。", nil, 0x9526a7f9, nil, "um" },
  [1231901] = { "BalnazzarがinfernalをScarlet Lightbearerの妨害に呼び出し、$N2ヤード以内に$N1のFireダメージを与え、命中したプレイヤーを$N3の間スタンさせます。", nil, 0x9526a7f9, nil, "um" },
