  [1231906] = { "BalnazzarがinfernalをScarlet Lightbearerの妨害に呼び出し、$N2ヤード以内に$N1のFireダメージを与え、命中したプレイヤーを$N3の間スタンさせます。", "スタンしています。", 0x9931ec1d, 0x27f95286, "uu" },
